import {readJson,writeJson,deploymentRoot} from './classic/scripts/local-production/common.mjs';
import {join} from 'node:path';
const candidate=await readJson(join(deploymentRoot,'candidate.json'));
if(!candidate?.id?.startsWith('2026-10-28T05-')) throw Error('Unexpected candidate');
const current=await readJson(join(deploymentRoot,'current.json'));
await writeJson(join(deploymentRoot,'previous.json'),current);
await writeJson(join(deploymentRoot,'current.json'),candidate);
await writeJson('analysis/projects-export-2026-10-28/release.json',candidate);
console.log({id:candidate.id,fingerprint:candidate.fingerprint});
